// Deferred fictional owner-import transactions. No portal/Gmail requests or real-data writes.
fn owner_import_item(req:&str)->Value{json!({"url":format!("https://www.naukri.com/job-listings-fictional-{req}"),"title":"Rust Engineer","employer":"Owner Reviewed Fictional Employer","description":"Fictional listing evidence","required_skills":["Rust"],"experience_min":0,"experience_max":2,"experience_requirement":"required","remote_type":"remote","location":"Remote"})}
async fn owner_import_call(c:&mut PgConnection,items:Value)->Result<Value>{owner_execution_call(c,"/api/v1/execution/naukri/import","POST",json!({"jobs":items})).await}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_import_inserts_unverified_reviewed_facts_and_reimport_preserves_human_columns(){
    let(mut c,_work)=listing_fixture().await;let item=owner_import_item("923456789012");let first=owner_import_call(&mut c,json!([item])).await.unwrap();assert_eq!(first["inserted_count"],1);let id=first["job_ids"][0].as_str().unwrap().parse::<Uuid>().unwrap();let job:Value=sqlx::query_scalar("SELECT to_jsonb(j) FROM jobs j WHERE id=$1").bind(id).fetch_one(&mut c).await.unwrap();assert_eq!(job["source_verification_status"],"requires_review");assert_eq!(job["discovery_metadata"]["data_provenance"]["provider_verified"],false);assert_eq!(job["discovery_metadata"]["data_provenance"]["method"],"owner_url");assert!(job["match_score"].is_null());sqlx::query("UPDATE jobs SET title='Human retained title',status='shortlisted',match_score=88,match_explanation='Retained owner decision' WHERE id=$1").bind(id).execute(&mut c).await.unwrap();let original_company=job["company_id"].clone();let mut correction=owner_import_item("923456789012");correction["employer"]=json!("Corrected Fictional Employer");correction["title"]=json!("Corrected Reviewed Role");let second=owner_import_call(&mut c,json!([correction])).await.unwrap();assert_eq!(second["updated_count"],1);assert_eq!(second["duplicate_count"],1);assert_eq!(second["job_ids"],first["job_ids"]);let saved:Value=sqlx::query_scalar("SELECT to_jsonb(j) FROM jobs j WHERE id=$1").bind(id).fetch_one(&mut c).await.unwrap();assert_eq!(saved["title"],"Human retained title");assert_eq!(saved["company_id"],original_company);assert_eq!(saved["status"],"shortlisted");assert_eq!(saved["match_score"].as_f64(),Some(88.));assert_eq!(saved["discovery_metadata"]["company_name"],"Corrected Fictional Employer");assert_eq!(saved["discovery_metadata"]["title"],"Corrected Reviewed Role");assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM job_source_observations WHERE job_id=$1").bind(id).fetch_one(&mut c).await.unwrap(),1);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_import_alert_requires_current_exact_candidate_and_normalization_failure_rolls_back_review(){
    let(mut c,_)=listing_fixture().await;let alert=Uuid::new_v4();let key=format!("nau_alert:{alert}");let candidate=json!({"id":alert,"state":"NEEDS_INPUT","expires_at":"2099-01-01T00:00:00Z","url":"https://www.naukri.com/job-listings-fictional-923456789012","private_evidence":"retained"});browser_save(&mut c,&key,candidate.clone()).await;let mut item=owner_import_item("923456789012");item["alert_candidate_id"]=json!(alert);let mut invalid=owner_import_item("923456789013");invalid["salary_currency"]=json!("bad");let before=browser_snapshot(&mut c).await;assert_eq!(owner_import_call(&mut c,json!([item,invalid])).await.unwrap_err(),Failure("invalid_naukri_import"));assert_eq!(browser_snapshot(&mut c).await,before);let mut wrong=owner_import_item("923456789014");wrong["alert_candidate_id"]=json!(alert);assert_eq!(owner_import_call(&mut c,json!([wrong])).await.unwrap_err(),Failure("invalid_naukri_import"));let result=owner_import_call(&mut c,json!([item])).await.unwrap();assert_eq!(result["inserted_count"],1);assert_eq!(browser_pref(&mut c,&key).await["state"],"OWNER_REVIEWED");let job:Value=sqlx::query_scalar("SELECT discovery_metadata FROM jobs WHERE id=$1").bind(result["job_ids"][0].as_str().unwrap().parse::<Uuid>().unwrap()).fetch_one(&mut c).await.unwrap();assert_eq!(job["data_provenance"]["method"],"owner_job_alert");assert_eq!(job["data_provenance"]["reference"],format!("gmail-alert:{alert}"));assert_eq!(browser_pref(&mut c,&key).await["private_evidence"],"retained");
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_import_source_ack_failure_rolls_back_candidate_company_job_and_observation(){
    let(mut c,_)=listing_fixture().await;let alert=Uuid::new_v4();let key=format!("nau_alert:{alert}");browser_save(&mut c,&key,json!({"id":alert,"state":"NEEDS_INPUT","expires_at":"2099-01-01T00:00:00Z","url":"https://www.naukri.com/job-listings-fictional-923456789012"})).await;let mut item=owner_import_item("923456789012");item["alert_candidate_id"]=json!(alert);let before=browser_snapshot(&mut c).await;let jobs:i64=sqlx::query_scalar("SELECT count(*) FROM jobs").fetch_one(&mut c).await.unwrap();let companies:i64=sqlx::query_scalar("SELECT count(*) FROM companies").fetch_one(&mut c).await.unwrap();sqlx::raw_sql("CREATE FUNCTION fixture_owner_import_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$;CREATE TRIGGER fixture_owner_import_drop BEFORE INSERT ON job_source_observations FOR EACH ROW EXECUTE FUNCTION fixture_owner_import_drop()").execute(&mut c).await.unwrap();assert_eq!(owner_import_call(&mut c,json!([item])).await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM jobs").fetch_one(&mut c).await.unwrap(),jobs);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM companies").fetch_one(&mut c).await.unwrap(),companies);sqlx::raw_sql("DROP TRIGGER fixture_owner_import_drop ON job_source_observations;DROP FUNCTION fixture_owner_import_drop()").execute(&mut c).await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_import_external_ats_identity_retains_existing_source_and_metadata(){
    let(mut c,_)=listing_fixture().await;let mut item=owner_import_item("923456789012");item["application_url"]=json!("https://jobs.lever.co/fictional/1234567890abcdef/apply?utm_source=test");let first=owner_import_call(&mut c,json!([item])).await.unwrap();let id=first["job_ids"][0].as_str().unwrap().parse::<Uuid>().unwrap();let canonical:String=sqlx::query_scalar("SELECT job_url FROM jobs WHERE id=$1").bind(id).fetch_one(&mut c).await.unwrap();assert_eq!(canonical,"https://jobs.lever.co/fictional/1234567890abcdef");let retained=json!({"source":"existing-provider","owner_history":"retain"});sqlx::query("UPDATE jobs SET source_platform='lever',discovery_metadata=$2 WHERE id=$1").bind(id).bind(&retained).execute(&mut c).await.unwrap();let second=owner_import_call(&mut c,json!([item])).await.unwrap();assert_eq!(second["job_ids"],first["job_ids"]);let job:Value=sqlx::query_scalar("SELECT to_jsonb(j) FROM jobs j WHERE id=$1").bind(id).fetch_one(&mut c).await.unwrap();assert_eq!(job["source_platform"],"lever");assert_eq!(job["discovery_metadata"],retained);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM job_source_observations WHERE job_id=$1").bind(id).fetch_one(&mut c).await.unwrap(),1);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_import_http_auth_closed_schema_and_missing_alert_validation(){
    let(mut c,_)=listing_fixture().await;let(url,stop,server)=http_fixture_values(browser_values()).await;let http=client();let path=format!("{url}/api/v1/execution/naukri/import");let data=json!({"jobs":[owner_import_item("923456789012")]});assert_eq!(http.post(&path).json(&data).send().await.unwrap().status(),401);assert_eq!(http.post(&path).bearer_auth(HOST_TOKEN).header("x-agent-client",BROWSER_EXTENSION).json(&data).send().await.unwrap().status(),403);assert_eq!(http.post(&path).bearer_auth(HOST_TOKEN).json(&json!({"jobs":[]})).send().await.unwrap().status(),422);let mut alert=owner_import_item("923456789012");alert["alert_candidate_id"]=json!(Uuid::new_v4());assert_eq!(http.post(&path).bearer_auth(HOST_TOKEN).json(&json!({"jobs":[alert]})).send().await.unwrap().status(),422);let response=http.post(&path).bearer_auth(HOST_TOKEN).json(&data).send().await.unwrap();assert_eq!(response.status(),200);assert_eq!(response.json::<Value>().await.unwrap()["inserted_count"],1);assert_eq!(http.get(&path).bearer_auth(HOST_TOKEN).send().await.unwrap().status(),405);assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'apply_budget:')").fetch_one(&mut c).await.unwrap(),0);stop.cancel();server.await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_owner_import_similarity_is_only_a_review_hint_and_different_requisitions_never_merge(){
    let(mut c,_)=listing_fixture().await;let first=owner_import_item("923456789012");let second=owner_import_item("923456789013");let result=owner_import_call(&mut c,json!([first,second])).await.unwrap();assert_eq!(result["inserted_count"],2);assert_ne!(result["job_ids"][0],result["job_ids"][1]);let second=result["job_ids"][1].as_str().unwrap();assert_eq!(result["possible_duplicates"][second],json!([result["job_ids"][0]]));assert_eq!(result["duplicate_count"],0);
}
